// Static favicon assets. Materialize once during build; no functions or runtime image requests.
const fs = require("node:fs");
const path = require("node:path");
const assets = {
  "favicon-48.png": "",
  "favicon-192.png": "",
  "favicon-512.png": "",
  "apple-touch-icon.png": "",
  "favicon.ico": ""
};
for (const [name, encoded] of Object.entries(assets)) {
 fs.writeFileSync(path.join(__dirname, name), Buffer.from(encoded, "base64"));
}
console.log("ThinkStore: five static browser icons ready.");
